    _deprecation_warning(__name__, 'BuildEnvironment.app', remove=(10, 0))
    self._app = app

@app.deleter
def app(self) -> None:
    _deprecation_warning(__name__, 'BuildEnvironment.app', remove=(10, 0))
    del self._app

@property
def _registry(self) -> SphinxComponentRegistry:
